-- Gan cap hoc cho bo fake data sau khi da chay migration 002_student_school_level.sql.
UPDATE Students
SET school_level = CASE school_id
    WHEN 'b0000000-0000-0000-0000-000000000001'::UUID THEN 'THCS'
